"""AXON-only chat: every answer is generated by the local causal Transformer."""
from __future__ import annotations

import importlib.util
from pathlib import Path
import re
import sys
import time

ROOT = Path(__file__).resolve().parent
TRAINER = ROOT / "LLM Train.py"
if not TRAINER.is_file():
    raise SystemExit('Place "CHAT.py" beside "LLM Train.py" and "BRAIN.db".')

spec = importlib.util.spec_from_file_location("axon_train", TRAINER)
core = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = core
spec.loader.exec_module(core)


class WordPacedPrinter:
    """Render whole words with >=0.5s between starts; BPE pieces are not words."""
    def __init__(self, minimum_seconds=0.5):
        self.minimum_seconds = max(0.5, float(minimum_seconds))
        self.started_at = time.monotonic()
        self.last_word_at = None
        self.pending = ""

    def _print_part(self, part):
        if part.strip():
            earliest = (self.last_word_at if self.last_word_at is not None
                        else self.started_at) + self.minimum_seconds
            remaining = earliest - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)
            self.last_word_at = time.monotonic()
        print(part, end="", flush=True)

    def on_piece(self, piece):
        self.pending += piece
        # Buffer BPE fragments until the following word boundary.
        while True:
            match = re.search(r"\s+", self.pending)
            if match is None:
                break
            end = match.end()
            part, self.pending = self.pending[:end], self.pending[end:]
            self._print_part(part)

    def finish(self):
        if self.pending:
            self._print_part(self.pending)
            self.pending = ""


def show_stats(db, vocab):
    step = int(core.get_meta(db, "transformer_steps", 0))
    validation = core.get_meta(db, "transformer_validation_loss", "not measured")
    merges = len(__import__("json").loads(core.get_meta(db, "bpe_merges_json", "[]")))
    print("AXON generation: neural autoregressive decoding only")
    print(f"Parameters: {core.PARAMETERS:,}")
    print(
        f"Transformer: {core.TRANSFORMER_LAYERS} layers | "
        f"{core.TRANSFORMER_HEADS} heads | width {core.TRANSFORMER_DIM} | "
        f"FFN {core.TRANSFORMER_FF}"
    )
    print(f"Context: {core.TRANSFORMER_CONTEXT} BPE tokens | output budget {core.MAX_GENERATION_TOKENS}")
    print(f"Tokenizer: {len(vocab):,} tokens | {merges:,} learned BPE merges")
    print(f"Training batches: {step:,} | validation loss: {validation}")
    print(f"BRAIN.db: {core.DB_PATH.stat().st_size / 1024**2:.1f} MiB / 15360 MiB")
    print(
        f"Neural lookahead: {core.GENERATION_LOOKAHEAD_BRANCHES} branches, "
        f"one speculative token each; minimum word-display interval 0.5 seconds."
    )
    print("No saved-answer retrieval, no canned greeting system, no external chat model.")


def main():
    np = core.ensure_numpy()
    print("AXON AI | standalone autoregressive Transformer")
    print(
        f"{core.PARAMETERS:,} parameters | {core.TRANSFORMER_LAYERS} layers | "
        f"{core.TRANSFORMER_HEADS} heads | {core.TRANSFORMER_CONTEXT}-token context"
    )
    print("Every response is generated token by token by AXON itself.")
    print(
        f"Deliberate search: {core.GENERATION_LOOKAHEAD_BRANCHES} neural branches "
        f"per token; at least 0.5 seconds between displayed words."
    )
    print("Type :help for commands.")

    with core.connection() as db:
        core.bootstrap_lessons(db)
        vocab = core.build_vocabulary(db)
        history = []
        trained_steps = int(core.get_meta(db, "transformer_steps", 0))
        if trained_steps:
            print(f"Loaded AXON checkpoint ({trained_steps:,} training batches).")
            validation = core.get_meta(db, "transformer_validation_loss", "n/a")
            print(f"Held-out validation loss: {validation}")
            if trained_steps < 10000:
                print(
                    "WARNING: This is still an experimental, undertrained model. "
                    "Generating tokens is not proof of fluent speech."
                )
        else:
            print('No trained checkpoint yet. Run: python "LLM Train.py"')

        while True:
            try:
                prompt = input("\nYou > ").strip()
            except (KeyboardInterrupt, EOFError):
                print("\nExiting. AXON checkpoint remains saved.")
                break
            if not prompt:
                continue

            lower = prompt.casefold()
            if lower in (":exit", ":quit", "exit", "quit"):
                break
            if lower == ":new":
                history.clear()
                print("Conversation context cleared.")
                continue
            if lower == ":help":
                print("Commands:")
                print("  :teach question => answer   Train AXON on your example")
                print("  :train 1200                 Train on saved examples")
                print("  :stats                      Show model and training details")
                print("  :new                        Clear the current conversation context")
                print("  :exit                       Quit")
                print("Generation is fixed to AXON's maximum configured context/output budget.")
                continue
            if lower == ":stats":
                vocab = core.build_vocabulary(db)
                show_stats(db, vocab)
                continue

            if lower.startswith(":teach "):
                pair = prompt[7:].split("=>", 1)
                if len(pair) != 2 or not pair[0].strip() or not pair[1].strip():
                    print("Use :teach question => answer")
                    continue
                question, answer = (part.strip() for part in pair)
                core.store_lesson(db, question, answer, "user")
                vocab = core.extend_vocabulary(db, question + " " + answer)
                db.commit()
                print(
                    "Saved the example. Training AXON on a mix of old and new "
                    "conversations to reduce overfitting..."
                )
                try:
                    core.learn_observations(db, np, steps=40)
                    print("AXON neural checkpoint updated.")
                except KeyboardInterrupt:
                    print("\nTraining interrupted; the latest checkpoint was saved.")
                continue

            if lower.startswith(":train"):
                try:
                    steps = int(prompt.split()[1])
                except (ValueError, IndexError):
                    steps = 1200
                if not 1 <= steps <= 100000:
                    print("Choose 1 through 100,000 training batches.")
                    continue
                try:
                    core.learn_observations(db, np, steps=steps)
                    vocab = core.build_vocabulary(db)
                except KeyboardInterrupt:
                    print("\nTraining interrupted; the latest checkpoint was saved.")
                continue

            if prompt.startswith(":"):
                print("Unknown command. Type :help.")
                continue

            trained_steps = int(core.get_meta(db, "transformer_steps", 0))
            if trained_steps <= 0:
                print('AXON has no trained weights yet. Run: python "LLM Train.py"')
                continue

            print("AXON > ", end="", flush=True)
            paced = WordPacedPrinter(minimum_seconds=0.5)
            try:
                answer = core.transformer_generate(
                    db, prompt,
                    length=core.MAX_GENERATION_TOKENS,
                    temperature=core.GENERATION_TEMPERATURE,
                    top_k=core.GENERATION_TOP_K,
                    top_p=core.GENERATION_TOP_P,
                    on_piece=paced.on_piece,
                    history=history
                )
                paced.finish()
                if not answer.strip():
                    print("[AXON generated no tokens. Train it on more text.]")
                else:
                    print()
                    history.append((prompt, answer))
                    history = history[-6:]
            except Exception as exc:
                print(f"\nAXON generation error: {exc}")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nExiting.")
